import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStreamWriter;
import java.net.InetAddress;
import java.net.InetSocketAddress;
import java.net.ServerSocket;
import java.net.Socket;
import java.nio.charset.StandardCharsets;
import java.util.Locale;

public class LineServerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    /**
     * Runs serveOnce on its own thread, talks to it as a client, then joins the
     * thread. Returns { reply, serverThreadError }.
     */
    static String[] round(ServerSocket server, String message) {
        final String[] serverError = new String[1];
        Thread thread = new Thread(() -> {
            try {
                LineServer.serveOnce(server);
            } catch (Throwable t) {
                serverError[0] = t.getClass().getSimpleName();
            }
        });
        thread.setDaemon(true);
        thread.start();

        String reply;
        Socket client = null;
        try {
            client = new Socket();
            client.connect(new InetSocketAddress(InetAddress.getByName("127.0.0.1"),
                    server.getLocalPort()), 1000);
            client.setSoTimeout(500);
            BufferedWriter out = new BufferedWriter(
                    new OutputStreamWriter(client.getOutputStream(), StandardCharsets.UTF_8));
            out.write(message);
            out.write("\n");
            out.flush();
            BufferedReader in = new BufferedReader(
                    new InputStreamReader(client.getInputStream(), StandardCharsets.UTF_8));
            String line = in.readLine();
            reply = (line == null) ? "server closed without replying" : line;
        } catch (Exception e) {
            reply = "no reply: " + e.getClass().getSimpleName();
        } finally {
            if (client != null) {
                try {
                    client.close();
                } catch (IOException ignored) {
                    // nothing useful to do
                }
            }
            try {
                thread.join(2000);
            } catch (InterruptedException ignored) {
                Thread.currentThread().interrupt();
            }
        }
        return new String[] { reply, serverError[0] };
    }

    public static void main(String[] args) throws Exception {
        ServerSocket server = null;
        String[] first = { "not run", null };
        String[] second = { "not run", null };
        boolean serverStillOpen = false;
        try {
            server = new ServerSocket(0, 8, InetAddress.getByName("127.0.0.1"));
            first = round(server, "hello sockets");
            second = round(server, "MiXeD case 123");
            serverStillOpen = !server.isClosed();
        } finally {
            if (server != null) {
                try {
                    server.close();
                } catch (IOException ignored) {
                    // nothing useful to do
                }
            }
        }

        check("first client gets its line back uppercased", "HELLO SOCKETS", first[0]);
        check("serveOnce threw nothing on the first call", null, first[1]);
        check("a second call serves the next client", "MIXED CASE 123", second[0]);
        check("serveOnce threw nothing on the second call", null, second[1]);
        check("serveOnce leaves the ServerSocket open for reuse", Boolean.TRUE,
                Boolean.valueOf(serverStillOpen));
        check("the reply really is uppercase", Boolean.TRUE,
                Boolean.valueOf(first[0] != null && first[0].equals(first[0].toUpperCase(Locale.ROOT))));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

